command:
TCCD=/var/mnt/rootfs/System/Library/PrivateFrameworks/TCC.framework/Support/tccd; /var/jb/usr/bin/sha256sum $TCCD; od -Ax -tx1 -N48 $TCCD | head -4; echo "---uuid via od---"; od -Ax -tx1 -j $(python3 - 2>/dev/null <<EOF
import struct,sys
d=open("$TCCD","rb").read(0x4000)
# parse minimal macho for LC_UUID
magic=struct.unpack("<I",d[:4])[0]
if magic==0xfeedfacf:
  n=struct.unpack("<I",d[16:20])[0]; off=32
  for i in range(n):
    cmd,sz=struct.unpack("<II",d[off:off+8])
    if cmd==0x1b:
      u=d[off+8:off+24]; print("UUID "+u.hex().upper()); break
    off+=sz
elif magic==0xcafebabe:
  print("FAT")
EOF
) $TCCD 2>/dev/null | head -3
